private data class PendingPageEffect(val invoke: Invoke, val play: Boolean, val volume: Float)
private var pageEffectPool: SoundPool? = null
private val pageEffectSamples = LinkedHashMap<String, Int>()
private val pageEffectPending = mutableMapOf<Int, MutableList<PendingPageEffect>>()
private val pageEffectFiles = mutableMapOf<Int, File>()
private var pageEffectStream = 0

// SoundPool mixes a short UI sound without requesting AudioManager focus.
// It deliberately shares neither the WebView media session nor the TTS player.
private fun getPageEffectPool(): SoundPool {
    pageEffectPool?.let { return it }
    val pool = SoundPool.Builder().setMaxStreams(1).setAudioAttributes(
        AudioAttributes.Builder()
            .setUsage(AudioAttributes.USAGE_ASSISTANCE_SONIFICATION)
            .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
            .build()
    ).build()
    pool.setOnLoadCompleteListener { soundPool, sample, status ->
        pageEffectFiles.remove(sample)?.delete()
        val waiting = pageEffectPending.remove(sample).orEmpty()
        if (status != 0) {
            pageEffectSamples.entries.removeAll { it.value == sample }
            waiting.forEach { it.invoke.reject("Short page effect could not be decoded") }
        } else {
            waiting.forEach { item ->
                if (item.play) playLoadedPageEffect(soundPool, sample, item.volume)
                item.invoke.resolve()
            }
            while (pageEffectSamples.size > 6) {
                val old = pageEffectSamples.entries.firstOrNull {
                    it.value != sample && !pageEffectPending.containsKey(it.value)
                } ?: break
                soundPool.unload(old.value)
                pageEffectSamples.remove(old.key)
            }
        }
    }
    pageEffectPool = pool
    return pool
}

private fun playLoadedPageEffect(pool: SoundPool, sample: Int, volume: Float) {
    if (pageEffectStream != 0) pool.stop(pageEffectStream)
    pageEffectStream = pool.play(sample, volume, volume, 1, 0, 1f)
    // Short local diagnostic for device QA; no paths or user content.
    if (pageEffectStream > 0) Log.d("ReadEatPageEffect", "play stream=$pageEffectStream gain=$volume")
    else Log.w("ReadEatPageEffect", "Short effect stream could not start")
}

@Command
fun page_effect_audio(invoke: Invoke) {
    val args = invoke.parseArgs(PageEffectAudioArgs::class.java)
    if (args.data.length > 160000 || args.data.isEmpty()) {
        invoke.reject("Invalid short page effect size")
        return
    }
    val volume = if (args.volume.isFinite()) args.volume.coerceIn(0f, 1f) else 0f
    activity.runOnUiThread {
        try {
            val bytes = Base64.decode(args.data, Base64.DEFAULT)
            if (bytes.size > 120000) throw IllegalArgumentException("Short page effect is too large")
            val key = MessageDigest.getInstance("SHA-256").digest(bytes)
                .joinToString("") { "%02x".format(it) }
            val pool = getPageEffectPool()
            val existing = pageEffectSamples[key]
            val item = PendingPageEffect(invoke, args.play && volume > 0f, volume)
            if (existing != null) {
                val pending = pageEffectPending[existing]
                if (pending != null) pending.add(item)
                else {
                    if (item.play) playLoadedPageEffect(pool, existing, volume)
                    invoke.resolve()
                }
            } else {
                val file = File.createTempFile("readeat-page-", ".audio", activity.cacheDir)
                file.writeBytes(bytes)
                val sample = pool.load(file.absolutePath, 1)
                if (sample == 0) {
                    file.delete()
                    throw IllegalStateException("Short page effect could not be loaded")
                }
                pageEffectSamples[key] = sample
                pageEffectFiles[sample] = file
                pageEffectPending[sample] = mutableListOf(item)
            }
        } catch (error: Exception) {
            invoke.reject("Short page effect unavailable: ${error.message}")
        }
    }
}

override fun onDestroy() {
    pageEffectPending.values.flatten().forEach { it.invoke.reject("Activity closed") }
    pageEffectPending.clear()
    pageEffectFiles.values.forEach { it.delete() }
    pageEffectFiles.clear()
    pageEffectSamples.clear()
    pageEffectPool?.release()
    pageEffectPool = null
    pixelCovers.values.toList().forEach { it.dismiss() }
    pixelCovers.clear()
    stopAmbientLightUpdatesInternal()
    inputManager?.unregisterInputDeviceListener(gamepadInputListener)

