  const folders = [
    { path: '/A', flatten: false },
    { path: '/A/nested', flatten: true },
    { path: '/B', flatten: false },
  ];
  it('unions overlapping folders once and preserves unrelated books and source files', () => {
    const books = [
      book('a', '/A/nested/a.epub'),
      book('b', '/B/b.epub', ['/A/b.epub']),
      book('c', '/C/c.epub'),
    ];
    expect(booksLinkedToWatchedFolders(books, ['/A', '/A/nested']).map((b) => b.hash)).toEqual([
      'a',
      'b',
    ]);
    expect(books[1]?.filePath).toBe('/B/b.epub');
    const settings = {
      autoImportFolders: ['/A', '/A/nested', '/B'],
      autoImportFlattenFolders: ['/A/nested'],
      externalLibraryFolders: ['/A', '/A/nested', '/B'],
      personalProfile: { manualBookOrders: { all: ['book:a', 'book:b', 'book:c', 'group:g'] } },
    } as unknown as SystemSettings;
    const next = removeWatchedFoldersPreferences(settings, ['/A/', '/A/nested'], ['a', 'b']);
    expect(next.autoImportFolders).toEqual(['/B']);
    expect(next.externalLibraryFolders).toEqual(['/B']);
    expect(next.autoImportFlattenFolders).toEqual([]);
    expect(next.personalProfile?.manualBookOrders?.['all']).toEqual(['book:c', 'group:g']);
    expect(settings.autoImportFolders).toHaveLength(3);
  });
