import { afterEach, describe, expect, it } from 'vitest';
import { curlDragFrameProgress, PageCurlRenderer } from '@/utils/pageCurl';

const tipDisplacement = (frame: number, width: number, grabY: number, columns: number) => {
  const leaf = columns >= 2;
  const leafWidth = leaf ? width / 2 : width;
  const radius = leaf
    ? 0.16 * leafWidth * (1 - frame * frame)
    : Math.max(12, 0.16 * width * (1 - 0.4 * frame));
  const travel = leaf ? leafWidth : width + Math.PI * Math.max(12, 0.16 * width * 0.6);
  const arc = Math.PI * Math.max(radius, 1e-3);
  const s = travel * frame;
  // Position of the original lifted edge after the vertex shader's bend.
  const along = s < arc ? s - radius * Math.sin(s / Math.max(radius, 1e-3)) : 2 * s - arc;
  return along / Math.hypot(1, (grabY - 0.5) * 1.8 * (1 - frame));
};

describe('finger distance to page curl frame', () => {
  it.each([
    [400, 700, 1],
    [800, 400, 1],
    [1968, 2184, 2],
    [96, 180, 1],
  ])('keeps the lifted edge at finger distance for %sx%s / %s columns', (width, height, columns) => {
    for (const y of [0.05, 0.5, 0.95]) {
      let previous = -1;
      for (const distance of [0, 0.02, 0.1, 0.2, 0.4, 0.6, 0.8, 1]) {
        const frame = curlDragFrameProgress(distance, width, height, y, columns);
        expect(frame).toBeGreaterThanOrEqual(previous);
        expect(frame).toBeGreaterThanOrEqual(0);
        expect(frame).toBeLessThanOrEqual(1);
        expect(Math.abs(tipDisplacement(frame, width, y, columns) - distance * width)).toBeLessThan(
          0.01,
        );
        previous = frame;
      }
    }
  });

  it('retains the physical remaining release travel after a full-width single-page drag', () => {
    const frame = curlDragFrameProgress(1, 400, 700, 0.5);
    expect(frame).toBeGreaterThan(0);
    expect(frame).toBeLessThan(1);
    expect(tipDisplacement(frame, 400, 0.5, 1)).toBeCloseTo(400, 3);
    expect(tipDisplacement(1, 400, 0.5, 1)).toBeGreaterThan(800);
  });

  it('clamps external samples without producing invalid frames', () => {
    expect(curlDragFrameProgress(-1, 400, 700, 0.5)).toBe(0);
    expect(curlDragFrameProgress(0, 400, 700, 0.5)).toBe(0);
    expect(curlDragFrameProgress(5, 400, 700, 0.5)).toBe(curlDragFrameProgress(1, 400, 700, 0.5));
    for (const invalid of [Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
      expect(curlDragFrameProgress(invalid, 400, 700, 0.5)).toBe(0);
      expect(curlDragFrameProgress(0.5, invalid, 700, 0.5)).toBe(0);
      expect(curlDragFrameProgress(0.5, 400, invalid, 0.5)).toBe(0);
      expect(curlDragFrameProgress(0.5, 400, 700, invalid)).toBe(
        curlDragFrameProgress(0.5, 400, 700, 0.5),
      );
    }
    expect(curlDragFrameProgress(0.5, 0, 700, 0.5)).toBe(0);
    expect(curlDragFrameProgress(0.5, 400, -1, 0.5)).toBe(0);
  });
});

describe('finger-follow curl on an actual WebGL mesh', () => {
  let renderer: PageCurlRenderer | undefined;
  let host: HTMLDivElement | undefined;
  afterEach(() => {
    renderer?.dispose();
    host?.remove();
  });

  it.each([
    [0.2, false],
    [0.6, false],
    [0.2, true],
    [0.6, true],
  ] as const)('draws the lifted edge under the finger at distance %s (rtl=%s)', (distance, rtl) => {
    const width = 400;
    const height = 300;
    host = document.createElement('div');
    document.body.append(host);
    const texture = document.createElement('canvas');
    texture.width = width;
    texture.height = height;
    const context = texture.getContext('2d')!;
    context.fillStyle = '#fff';
    context.fillRect(0, 0, width, height);
    context.fillStyle = '#000';
    context.fillRect(rtl ? 0 : width - 16, 0, 16, height);
    renderer = new PageCurlRenderer();
    renderer.attach(host, width, height, 1);
    renderer.setTexture(texture);
    const frame = curlDragFrameProgress(distance, width, height, 0.5);
    renderer.render(frame, { x: rtl ? 0 : 1, y: 0.5 }, rtl);

    // A black stripe at the lifted edge remains visible next to the actual
    // finger position. Raw distance-as-frame sweeps this stripe too far away.
    const tipX = (rtl ? distance : 1 - distance) * width;
    const samples = [];
    for (let offset = 2; offset <= 18; offset += 2) {
      samples.push(renderer.readPixel(Math.round(tipX + (rtl ? -offset : offset)), height / 2));
    }
    expect(samples.some(([r, g, b, a]) => a === 255 && r < 210 && g < 210 && b < 210)).toBe(true);
    expect(renderer.isUsable()).toBe(true);
  });
});

import { expect, it, vi } from 'vitest';
import { CapturedPageTurn, type CapturedTurnHost } from '@/app/reader/utils/capturedTurn';
import { curlDragFrameProgress, PageCurlRenderer } from '@/utils/pageCurl';

it.each([
  [true, false, false],
  [true, false, true],
  [true, true, false],
  [true, true, true],
  [false, false, false],
  [false, false, true],
  [false, true, false],
  [false, true, true],
])('scrubs the calibrated mesh and settles without changing the reading position unexpectedly (forward=%s rtl=%s commit=%s)', async (forward, rtl, commit) => {
  const width = 400;
  const height = 300;
  const host = document.createElement('div');
  host.style.cssText = `position:relative;width:${width}px;height:${height}px`;
  document.body.append(host);
  let page = 2;
  const frames: number[] = [];
  const usable: boolean[] = [];
  const original = PageCurlRenderer.prototype.render;
  const spy = vi.spyOn(PageCurlRenderer.prototype, 'render');
  spy.mockImplementation(function (this: PageCurlRenderer, progress, grab, mirror) {
    original.call(this, progress, grab, mirror);
    frames.push(progress);
    usable.push(this.isUsable());
  });
  const uncover = vi.fn(async () => {});
  const controller = new CapturedPageTurn({
    trackFinger: true,
    getHostElement: () => host,
    getContentRect: () => new DOMRect(0, 0, width, height),
    capture: async () => {
      const texture = document.createElement('canvas');
      texture.width = width;
      texture.height = height;
      const context = texture.getContext('2d')!;
      context.fillStyle = page === 2 ? 'blue' : 'red';
      context.fillRect(0, 0, width, height);
      return createImageBitmap(texture);
    },
    coverRegion: async () => uncover,
    navigate: async (next) => {
      page += next ? 1 : -1;
    },
    getMotion: () => ({ preset: 'apple', duration: 150, radius: 0.16, tilt: 1.8 }),
  } satisfies CapturedTurnHost);
  try {
    expect(await controller.beginDrag(forward, rtl)).toBe(true);
    const held: number[] = [];
    for (const distance of [0.2, 0.45, 0.65]) {
      controller.moveDrag(distance, 0.5);
      const frame = curlDragFrameProgress(distance, width, height, 0.5);
      expect(frames.at(-1)).toBeCloseTo(forward ? frame : 1 - frame, 7);
      held.push(frames.at(-1)!);
      expect(host.querySelector('canvas')).not.toBeNull();
    }
    expect(forward ? held[2]! > held[0]! : held[2]! < held[0]!).toBe(true);
    expect(usable.every(Boolean)).toBe(true);
    const release = frames.at(-1)!;
    const releaseIndex = frames.length;
    await controller.endDrag(commit);
    const terminal = forward ? (commit ? 1 : 0) : commit ? 0 : 1;
    const settleFrames = frames.slice(releaseIndex);
    expect(settleFrames.length).toBeGreaterThan(0);
    expect(frames.at(-1)).toBeCloseTo(terminal, 7);
    let previous = release;
    for (const frame of settleFrames) {
      expect(terminal > release ? frame >= previous : frame <= previous).toBe(true);
      previous = frame;
    }
    expect(page).toBe(commit ? (forward ? 3 : 1) : 2);
    expect(host.querySelector('canvas')).toBeNull();
