import { cleanup, renderHook, waitFor } from '@testing-library/react';
const mocked = vi.hoisted(() => ({ request: vi.fn() }));
vi.mock('@/utils/permission', () => ({ requestStoragePermission: mocked.request }));
import { useStartupStoragePermission } from '@/hooks/useStartupStoragePermission';
describe('initial Android storage access', () => {
  beforeEach(() => {
    localStorage.clear();
    mocked.request.mockReset().mockResolvedValue(false);
  });
  afterEach(() => cleanup());
  it('asks immediately on first main-library mount and does not loop after denial', async () => {
    const first = renderHook(() => useStartupStoragePermission(true));
    await waitFor(() => expect(mocked.request).toHaveBeenCalledOnce());
    first.unmount();
    renderHook(() => useStartupStoragePermission(true));
    expect(mocked.request).toHaveBeenCalledOnce();
  });
  it('does not open permissions on web or popup mounts', () => {
    renderHook(() => useStartupStoragePermission(false));
    expect(mocked.request).not.toHaveBeenCalled();
    expect(localStorage.length).toBe(0);
  });
  it('waits until the native environment is ready', async () => {
    const hook = renderHook(({ ready }) => useStartupStoragePermission(ready), {
      initialProps: { ready: false },
    });
    expect(mocked.request).not.toHaveBeenCalled();
    hook.rerender({ ready: true });
    await waitFor(() => expect(mocked.request).toHaveBeenCalledOnce());
  });
  it('does not throw if the permission bridge is unavailable', async () => {
    mocked.request.mockRejectedValueOnce(Error('bridge not ready'));
    renderHook(() => useStartupStoragePermission(true));
    await waitFor(() => expect(mocked.request).toHaveBeenCalledOnce());
    await waitFor(() => expect(localStorage.getItem('readeat.storage-access-intro.v1')).toBeNull());
  });
});

