import { useEffect, useRef } from 'react';
import { requestStoragePermission } from '@/utils/permission';

const STORAGE_INTRO_KEY = 'readeat.storage-access-intro.v1';

/** Mounted only by the main library, never by dictionary/browser popups.
 * All-files access opens Android Settings; returning or denying must not
 * reopen it in a loop. The normal import action remains an explicit retry. */
export function useStartupStoragePermission(isAndroidMainLibrary: boolean) {
  const attempted = useRef(false);
  useEffect(() => {
    if (!isAndroidMainLibrary || attempted.current) return;
    attempted.current = true;
    try {
      if (localStorage.getItem(STORAGE_INTRO_KEY)) return;
      localStorage.setItem(STORAGE_INTRO_KEY, '1');
    } catch {
      // The in-memory guard still prevents repeated requests on this mount.
    }
    void requestStoragePermission().catch((error: unknown) => {
      try {
        localStorage.removeItem(STORAGE_INTRO_KEY);
      } catch {}
      console.debug('Initial storage access unavailable', error);
    });
  }, [isAndroidMainLibrary]);
}

