import { invoke } from '@tauri-apps/api/core';
import { getInitializedAppService } from '@/services/environment';

const nativeData = new Map<string, Promise<string>>();
const browserSounds = new Map<string, HTMLAudioElement>();
const gain = (volume: number) => Math.max(0, Math.min(1, Number.isFinite(volume) ? volume : 0));

async function effectData(source: string): Promise<string> {
  if (source.startsWith('data:audio/')) {
    if (
      !/^data:audio\/(?:mpeg|mp3|wav|x-wav|wave|ogg|mp4|x-m4a);base64,[a-z0-9+/=]+$/i.test(
        source,
      ) ||
      source.length > 160000
    )
      throw new Error('Invalid short page effect');
    return source.slice(source.indexOf(',') + 1);
  }
  if (!/^\/personal-sounds\/(?:paper|book|soft)\.mp3$/.test(source))
    throw new Error('Unsupported page effect source');
  const response = await fetch(source);
  if (!response.ok) throw new Error('Page effect could not be loaded');
  const bytes = new Uint8Array(await response.arrayBuffer());
  if (bytes.length > 120000) throw new Error('Page effect is too large');
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

async function nativeEffect(source: string, volume: number, play: boolean) {
  let pending = nativeData.get(source);
  if (!pending) {
    pending = effectData(source);
    nativeData.set(source, pending);
    // Settings allow three built-ins and three custom clips. Discard old JS
    // encodings when a user repeatedly replaces their custom recordings.
    if (nativeData.size > 6) nativeData.delete(nativeData.keys().next().value!);
    void pending.catch(() => nativeData.delete(source));
  }
  await invoke('plugin:native-bridge|page_effect_audio', {
    payload: { source, data: await pending, volume: gain(volume), play },
  });
}

function browserEffect(source: string) {
  let audio = browserSounds.get(source);
  if (!audio) {
    audio = new Audio(source);
    audio.preload = 'auto';
    browserSounds.set(source, audio);
    if (browserSounds.size > 6) {
      const oldest = browserSounds.keys().next().value!;
      browserSounds.get(oldest)?.pause();
      browserSounds.delete(oldest);
    }
  }
  return audio;
}

export async function primePageEffect(source: string): Promise<void> {
  if (getInitializedAppService()?.isAndroidApp) {
    await nativeEffect(source, 0, false);
    return;
  }
  browserEffect(source).load();
}

/** Short UI effect, separate from narration and Chromium's media/audio focus.
 * Never fall back to HTMLAudio on Android: it would duck the user's music. */
export async function playPageEffect(source: string, volume: number): Promise<void> {
  const volumeGain = gain(volume);
  if (volumeGain === 0) return;
  if (getInitializedAppService()?.isAndroidApp) {
    await nativeEffect(source, volumeGain, true);
    return;
  }
  const audio = browserEffect(source);
  audio.volume = volumeGain;
  audio.pause();
  audio.currentTime = 0;
  await audio.play();
}
